251	LiaStarExtension::LiaStarExtension(Env& env, TheoryArith& containing)
252	    : EnvObj(env),
253	      d_nm(nodeManager()),
254	      d_arith(containing),
255	      d_astate(*containing.getTheoryState()),
256	      d_im(containing.getInferenceManager()),
257	      d_checkCounter(0),
258	      d_extTheoryCb(),
259	      d_extTheory(env, d_extTheoryCb, d_im),
260	      d_hasLiaStarTerms(context(), false)
261	{
262	  d_extTheory.addFunctionKind(Kind::STAR_CONTAINS);
263	  d_true = nodeManager()->mkConst(true);
264	  d_false = nodeManager()->mkConst(false);
265	  d_zero = nodeManager()->mkConstInt(Rational(0));
266	  d_one = nodeManager()->mkConstInt(Rational(1));
267	  // Proofs are produced lazily; allocate the generator only when needed.
268	  if (env.isTheoryProofProducing())
269	  {
270	    d_proofGen.reset(new LiaStarProofGenerator(env, env.getUserContext()));
271	  }
272	}
