287	void LiaStarExtension::getAssertions(std::vector<Node>& assertions)
288	{
289	  // Collect the STAR_CONTAINS atoms among the arithmetic facts. Both polarities
290	  // are reduced to the positive atom: a negated `(not (star-contains ...))` is
291	  // handled by the same reduction lemma `literal = star` (the surrounding SAT
292	  // solver applies the negation).
293	  Trace("liastar-ext") << "Getting assertions..." << std::endl;
294	  Trace("liastar-ext") << "---------------------" << std::endl;
295	  for (auto it = d_arith.facts_begin(); it != d_arith.facts_end(); ++it)
296	  {
297	    Node lit = (*it).d_assertion;
298	    Trace("liastar-ext") << lit << std::endl;
299	    if (lit.getKind() == Kind::STAR_CONTAINS)
300	    {
301	      // positive polarity of star-contains
302	      assertions.push_back(lit);
303	    }
304	    if (lit.getKind() == Kind::NOT && lit[0].getKind() == Kind::STAR_CONTAINS)
305	    {
306	      // negative polarity of star-contains
307	      assertions.push_back(lit[0]);
308	    }
309	  }
310	  Trace("liastar-ext") << "---------------------" << std::endl;
311	}
312	
313	void LiaStarExtension::checkFullEffort(std::map<Node, Node>& arithModel,
314	                                       const std::set<Node>& termSet)
315	{
316	  // Last-call effort check: for each STAR_CONTAINS assertion emit the necessary
317	  // lemmas and, if the current model does not already satisfy the literal,
318	  // refine via the eager or lazy star reduction.
319	  Trace("liastar-ext") << "interceptModel: do model-based refinement"
320	                       << std::endl;
321	  Trace("liastar-ext") << " model is : " << arithModel << std::endl;
322	  Trace("liastar-ext") << " termSet is: " << termSet << std::endl;
323	  d_checkCounter++;
324	
325	  // get the assertions
326	  std::vector<Node> assertions;
327	  getAssertions(assertions);
328	
329	  Trace("liastar-ext") << "liastar assertions: " << assertions << std::endl;
330	  NodeManager* nm = nodeManager();
331	  for (const auto& literal : assertions)
332	  {
333	    Node lambda = literal[0];
334	    Assert(literal.getKind() == Kind::STAR_CONTAINS);
335	    // vectorPredicate = p[v] (v satisfies p) and nonnegative = (and (>= v_i 0)).
336	    auto [vectorPredicate, nonnegative] =
337	        LiaStarUtils::getVectorPredicate(literal, nm);
338	
339	    // (1) Membership in S* requires v to be in the non-negative orthant.
340	    if (d_proofGen != nullptr)
341	    {
342	      d_proofGen->registerNonnegative(nonnegative, literal);
343	    }
344	    d_im.addPendingLemma(
345	        nonnegative, InferenceId::ARITH_LIA_STAR_NONNEGATIVE, d_proofGen.get());
346	
347	    // (2) Split on whether v itself satisfies p: if so, v is a single-summand
348	    // member of S* and the literal holds directly.
349	    Node split = vectorPredicate.orNode(vectorPredicate.notNode());
350	    if (d_proofGen != nullptr)
351	    {
352	      d_proofGen->registerSplit(split, vectorPredicate);
353	    }
354	    d_im.addPendingLemma(
355	        split, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
356	    d_im.doPendingLemmas();
357	    if (d_im.hasSentLemma())
358	    {
359	      Trace("liastar-ext") << "Sending lemma: " << split << std::endl;
360	      continue;
361	    }
362	    if (options().arith.arithLiaStarModelValue)
363	    {
364	      // Model-value shortcut: if the current arithmetic model already satisfies
365	      // the predicate p[v] (or the last computed star under-approximation),
366	      // then the literal holds in this model and no further refinement is
367	      // needed this round.
368	      std::vector<Node> keys;
369	      std::vector<Node> values;
370	
371	      for (const auto& [key, value] : arithModel)
372	      {
373	        keys.push_back(key);
374	        values.push_back(value);
375	      }
376	
377	      // F: the membership predicate. Additionally consider the last computed
378	      // starLia under-approximation, if any: if the model already satisfies
379	      // F or that under-approximation, the literal already holds and no further
380	      // refinement is needed.
381	      Node f = vectorPredicate;
382	      auto starIt = d_lastStarLia.find(literal);
383	      Node check = starIt != d_lastStarLia.end() ? f.orNode(starIt->second) : f;
384	
385	      Node value = check.substitute(
386	          keys.begin(), keys.end(), values.begin(), values.end());
387	      value = rewrite(value);
388	
389	      Trace("liastar-ext-debug") << "value: " << value << std::endl;
390	
391	      if (value == d_true)
392	      {
393	        Trace("liastar-ext-debug")
394	            << "----------------------------------------" << std::endl;
395	        Trace("liastar-ext-debug")
396	            << literal << " is satisfied in the current model" << std::endl;
397	        Trace("liastar-ext-debug")
398	            << "----------------------------------------" << std::endl;
399	        return;
400	      }
401	    }
402	    // (3) Refine: reduce the star literal to its cone/Hilbert-basis encoding.
403	    if (options().arith.arithLiaStarLazy)
404	    {
405	      if (options().arith.arithLiaStarMainSolver)
406	      {
407	        mainSolverCheckStar(literal, lambda, arithModel);
408	      }
409	      else
410	      {
411	        lazyCheckStar(literal, lambda);
412	      }
413	    }
414	    else
415	    {
416	      eagerCheckStar(literal, lambda);
417	    }
418	  }
419	}
420	
421	void LiaStarExtension::eagerCheckStar(Node literal, Node lambda)
422	{
423	  // Eager reduction: compute every cone of p up front and emit the exact
424	  // equivalence `literal = star`. Each literal is reduced at most once.
425	  if (std::find(
426	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
427	      != d_processedStarTerms.end())
428	  {
429	    return;
430	  }
431	  // Normalize p to DNF and render each disjunct as a Normaliz constraint matrix.
432	  std::vector<std::pair<std::vector<std::string>, Node>> pairs =
433	      convertQFLIAToMatrices(lambda);
434	
435	  // Build the cones and the star constraints over all of them.
436	  auto [cones, starConstraints] = getCones(literal, pairs);
437	
438	  if (TraceIsOn("liastar-ext-smt"))
439	  {
440	    // Debug only: build the per-cone membership encoding (v in S, a single
441	    // element) and emit (check-sat) queries asserting it is equivalent to the
442	    // predicate, so a separate solver run can validate the cone decomposition.
443	    // The actual lemma below uses `starConstraints`, not `lia`.
444	    std::vector<std::pair<Node, Node>> lia =
445	        getMembershipDisjuncts(lambda, cones);
446	    Trace("liastar-ext") << "lia constraint: " << std::endl;
447	    traceMembershipValidation(d_nm, lambda, lia);
448	  }
449	  Node star = d_nm->mkNode(Kind::AND, starConstraints);
450	  Trace("liastar-ext") << "starConstraints: " << std::endl
451	                       << toString(starConstraints) << std::endl;
452	  star = rewrite(star);
453	  Node lemma = literal.eqNode(star);
454	  Trace("liastar-ext") << "star lemma: " << lemma << std::endl;
455	  if (d_proofGen != nullptr)
456	  {
457	    d_proofGen->registerContainsReduce(lemma, literal, star);
458	  }
459	  d_im.addPendingLemma(
460	      lemma, InferenceId::ARITH_LIA_STAR_EXISTS, d_proofGen.get());
461	  d_processedStarTerms.push_back(literal);
462	  d_im.doPendingLemmas();
463	}
