796	const std::vector<std::pair<std::vector<std::string>, Node>>
797	LiaStarExtension::convertQFLIAToMatrices(Node n)
798	{
799	  // Normalize the lambda body `p` to DNF and render each disjunct as a Normaliz
800	  // constraint matrix (one cone per disjunct). `n` is the lambda
801	  // (lambda ((x_1 Int) ... (x_n Int)) p).
802	  Assert(n.getKind() == Kind::LAMBDA);
803	
804	  Node variables = n[0];
805	  Node predicate = n[1];
806	  Trace("liastar-ext") << "convertQFLIAToMatrices::n: " << n << std::endl;
807	  Trace("liastar-ext") << "variables: " << variables << std::endl;
808	
809	  Trace("liastar-ext") << "predicate: " << predicate << std::endl;
810	
811	  traceSmtPreamble(variables);
812	
813	  Node dnf = LiaStarUtils::toDNF(predicate, &d_env);
814	
815	  Trace("liastar-ext") << "predicate in dnf: " << dnf << std::endl;
816	  Trace("liastar-ext") << "lia constraint: " << std::endl;
817	
818	  std::vector<std::pair<std::vector<std::string>, Node>> pairs =
819	      LiaStarUtils::getMatrices(variables, dnf);
820	  return pairs;
821	}
