1038	void LiaStarExtension::mainSolverCheckStar(
1039	    Node literal, Node lambda, const std::map<Node, Node>& arithModel)
1040	{
1041	  // Main-solver lazy reduction: drive one refinement round for `literal`,
1042	  // enumerating the predicate's cells in the main solver instead of a
1043	  // dedicated subsolver. Stop refining once the literal has been fully
1044	  // reduced.
1045	  if (std::find(
1046	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
1047	      != d_processedStarTerms.end())
1048	  {
1049	    return;
1050	  }
1051	
1052	  bool seeded = d_mainEnums.find(lambda) != d_mainEnums.end();
1053	  MainEnum& en = getMainEnum(lambda);
1054	
1055	  // Catch up: open one stage per cone-disjunct discovered since the previous
1056	  // round (e.g. through another literal with the same lambda). The disjuncts
1057	  // are stored in bound-variable space, so map them to skolem space first.
1058	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& pairs =
1059	      d_lazyCones[lambda];
1060	  for (size_t i = en.negated; i < pairs.size(); i++)
1061	  {
1062	    Node disjunct = pairs[i].first;
1063	    if (!en.from.empty())
1064	    {
1065	      disjunct = disjunct.substitute(
1066	          en.from.begin(), en.from.end(), en.to.begin(), en.to.end());
1067	    }
1068	    advanceStage(en, disjunct);
1069	  }
1070	  en.negated = pairs.size();
1071	
1072	  if (!seeded)
1073	  {
1074	    // First round: the seed lemmas were only queued just now, so there is no
1075	    // assignment of the guard or the skolems to read yet. The driver lemma
1076	    // makes an unjustified literal activate the enumeration.
1077	    emitDriverLemma(literal, en);
1078	    d_im.doPendingLemmas();
1079	    return;
1080	  }
1081	
1082	  Valuation& val = d_astate.getValuation();
1083	  bool guardValue = false;
1084	  bool assigned = val.isSatLiteral(en.guard)
1085	                  && val.hasSatValue(en.guard, guardValue);
1086	  if (assigned && !guardValue && val.isFixed(en.guard))
1087	  {
1088	    // The negated stage guard is implied by the input assertions: the
1089	    // predicate conjoined with the negated disjuncts is unsatisfiable, so
1090	    // every cell of the predicate is covered by a cone and the encoding is
1091	    // exact (this is the analogue of the subsolver answering unsat).
1092	    processDisjunct(literal, d_false, /*complete=*/true);
1093	    return;
1094	  }
1095	  if (!assigned || !guardValue)
1096	  {
1097	    // No cell can be read this round. (Re-)emit the driver for the current
1098	    // stage: a model claiming the literal without certifying it cannot then
1099	    // be accepted, since the driver forces the stage guard in any such
1100	    // model, and the model-value shortcut in checkFullEffort accepts the
1101	    // certified ones.
1102	    emitDriverLemma(literal, en);
1103	    d_im.doPendingLemmas();
1104	    return;
1105	  }
1106	
1107	  // The stage guard is true: the skolems lie in a region of the predicate
1108	  // not covered by any cone. Read off the cell containing them.
1109	  Node disjunct = getModelDisjunct(en, arithModel);
1110	  Trace("liastar-ext") << "main-solver disjunct: " << disjunct << std::endl;
1111	  if (disjunct.isNull())
1112	  {
1113	    // some atom had no model value; try again next round
1114	    emitDriverLemma(literal, en);
1115	    d_im.doPendingLemmas();
1116	    return;
1117	  }
1118	  // Guard against re-harvesting a known cell (its negation lemma may not
1119	  // have reached the solver before this model was produced).
1120	  for (const auto& pair : pairs)
1121	  {
1122	    if (pair.first == disjunct)
1123	    {
1124	      emitDriverLemma(literal, en);
1125	      d_im.doPendingLemmas();
1126	      return;
1127	    }
1128	  }
1129	  // Open the stage that excludes the new cell, so the continuing search
1130	  // moves the skolems to another cell.
1131	  Node skolemDisjunct = disjunct;
1132	  if (!en.from.empty())
1133	  {
1134	    skolemDisjunct = skolemDisjunct.substitute(
1135	        en.from.begin(), en.from.end(), en.to.begin(), en.to.end());
1136	  }
1137	  advanceStage(en, skolemDisjunct);
1138	  // Turn the cell into a cone and emit the (tentative) reduction lemma.
1139	  // `processDisjunct` appends the cone to `d_lazyCones[lambda]`, which the
1140	  // stage above has already negated, and updates the star
1141	  // under-approximation that the new driver lemma references.
1142	  processDisjunct(literal, disjunct, /*complete=*/false);
1143	  en.negated = pairs.size();
1144	  emitDriverLemma(literal, en);
1145	  d_im.doPendingLemmas();
1146	}
1147	
1148	void LiaStarExtension::lazyHilbert(Node literal, Subsolver& sub)
1149	{
1150	  // One lazy refinement round for `literal`. Ask the subsolver for a model in a
1151	  // region of p not yet covered by a cone, read off the convex cell containing
1152	  // it, and hand it to `processDisjunct` for the cone and lemma generation.
1153	  Node variables = literal[0][0];
1154	  Trace("liastar-lazy") << "lazyHilbert::variables:" << variables << std::endl;
1155	
1156	  traceSmtPreamble(variables);
1157	
1158	  // Check the subsolver and read off the disjunct (the cell of the predicate)
1159	  // containing the model. The subsolver already has the predicate and the
1160	  // negations of all previously discovered cone-disjuncts asserted, so the
1161	  // model lies in a region of the predicate not yet covered by any cone.
1162	  Node disjunct = LiaStarUtils::getDisjunct(
1163	      sub.base, sub.from, sub.to, &d_env, sub.engine.get());
1164	  // `getDisjunct` returns false when no region of `formula` is left uncovered,
1165	  // i.e. every disjunct of the predicate already has a cone. At that point the
1166	  // cone encoding is exact and we can assert the full equivalence.
1167	  bool complete = disjunct == d_false;
1168	  processDisjunct(literal, disjunct, complete);
1169	}
1170	
1171	void LiaStarExtension::processDisjunct(Node literal,
1172	                                       Node disjunct,
1173	                                       bool complete)
1174	{
1175	  // Shared tail of one lazy refinement round: turn the freshly discovered
1176	  // disjunct (a cell of the predicate, in bound-variable space) into a cone,
1177	  // rebuild the star constraints over all cones found so far, and emit a
1178	  // (tentative or final) reduction lemma.
1179	  Node variables = literal[0][0];
1180	  // The disjunct is a conjunction of arithmetic facts in the solver's normal
1181	  // form, which can represent strict inequalities as negations (e.g.
1182	  // (not (>= a b))). Normalize away the negations before building the matrix.
1183	  disjunct = LiaStarUtils::removeItesAndNots(disjunct, &d_env);
1184	
1185	  Trace("liastar-ext") << "disjunct: " << disjunct << std::endl;
1186	
1187	  std::pair<std::vector<std::string>, Node> pair =
1188	      LiaStarUtils::getMatrix(variables, disjunct);
1189	
1190	  // Add the cone for the current disjunct to `d_lazyCones` and get the starLia
1191	  // constraints over the whole list of cones so far. `getStarConstraints` only
1192	  // computes the per-cone constraints (and fresh skolems) for cones not yet
1193	  // processed, reusing the constraints computed in previous calls. When
1194	  // `complete`, `disjunct` is the (infeasible) false constraint, so `addCone`
1195	  // adds no new cone and `getStarConstraints` just rebuilds the sum constraints
1196	  // over the cones found so far.
1197	  addCone(literal, pair);
1198	  std::vector<Node> starConstraints = getStarConstraints(literal);
1199	  Trace("liastar-ext") << "starConstraints: " << std::endl
1200	                       << toString(starConstraints) << std::endl;
1201	
1202	  Node star = d_nm->mkNode(Kind::AND, starConstraints);
1203	
1204	  Trace("liastar-ext") << d_lazyCones[literal[0]].size()
1205	                       << " cones for lambda:  " << literal[0] << std::endl;
1206	
1207	  star = rewrite(star);
1208	  // Remember the last computed starLia under-approximation for `literal`; the
1209	  // model-value check in checkFullEffort uses it to skip refinement when the
1210	  // current model already satisfies it.
1211	  d_lastStarLia[literal] = star;
1212	
1213	  // Deactivate the guard from the previous refinement round for this literal:
1214	  // its under-approximation is a subset of the current `star`, so the tentative
1215	  // equivalence it guarded is subsumed. Asserting `(not g_old)` makes that
1216	  // guarded lemma vacuous, so the solver does not have to satisfy several
1217	  // (mutually constraining) guarded equivalences at once. Sound because `g_old`
1218	  // is fresh.
1219	  auto guardIt = d_lastGuard.find(literal);
1220	  if (guardIt != d_lastGuard.end())
1221	  {
1222	    Node deactivate = guardIt->second.notNode();
1223	    if (d_proofGen != nullptr)
1224	    {
1225	      d_proofGen->registerGuardDeactivate(deactivate);
1226	    }
1227	    d_im.addPendingLemma(
1228	        deactivate, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
1229	    d_lastGuard.erase(guardIt);
1230	  }
1231	
1232	  Node lemma;
1233	  if (complete)
1234	  {
1235	    // The encoding is complete, so `star` captures the star set exactly and the
1236	    // full equivalence holds. This is what allows refuting a (positively
1237	    // asserted) star-contains.
1238	    lemma = literal.eqNode(star);
1239	  }
1240	  else
1241	  {
1242	    // While cones are still being discovered, `star` is an under-approximation
1243	    // of the star set, so the equivalence `literal = star` is not yet sound. We
1244	    // assert it only tentatively, implied by a fresh boolean guard `g`. The
1245	    // split makes `g` a genuine decision literal and `preferPhase` biases it to
1246	    // true, so the SAT solver tries the equivalence first. If assuming it leads
1247	    // to a conflict (the literal actually holds via a not-yet-discovered cone),
1248	    // the solver flips `g` to false, retracting the equivalence, and we refine.
1249	    Node g = d_nm->mkDummySkolem("liastarGuard", d_nm->booleanType());
1250	    g = d_astate.getValuation().ensureLiteral(g);
1251	    d_im.preferPhase(g, true);
1252	    Node split = g.orNode(g.notNode());
1253	    if (d_proofGen != nullptr)
1254	    {
1255	      d_proofGen->registerSplit(split, g);
1256	    }
1257	    d_im.addPendingLemma(
1258	        split, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
1259	    lemma = g.impNode(literal.eqNode(star));
1260	    // Remember this guard so it can be deactivated once a later, larger
1261	    // under-approximation subsumes it.
1262	    d_lastGuard[literal] = g;
1263	  }
1264	  Trace("liastar-ext") << "star lemma: " << lemma << std::endl;
1265	  if (d_proofGen != nullptr)
1266	  {
1267	    d_proofGen->registerContainsReduce(lemma, literal, star);
1268	  }
1269	  d_im.addPendingLemma(
1270	      lemma, InferenceId::ARITH_LIA_STAR_EXISTS, d_proofGen.get());
1271	  // Keep refining (do not mark the term processed) until every disjunct of the
1272	  // predicate has been covered by a cone.
1273	  if (complete)
1274	  {
1275	    d_processedStarTerms.push_back(literal);
1276	  }
1277	  d_im.doPendingLemmas();
1278	}
